struct Node { int val; Node* next; };

void insertHead(Node*& head, int v) {
    Node* n = new Node{v, nullptr};
    n->next = head;        // 1: new points at old first
    head = n;              // 2: head points at new
}
void insertAfter(Node* p, int v) {
    p->next = new Node{v, p->next};
}
void eraseAfter(Node* p) {
    Node* dead = p->next;
    p->next = dead->next;  // skip over it
    delete dead;           // then free it
}
